.stage {
  --bg: #0b0f14; --ink: #f4f6f8; --muted: #8a94a3; --accent: #5eead4; --accent-soft: #134e4a; --surface: #151b24;
  --arrive: cubic-bezier(0.19, 1, 0.22, 1);        /* expo-out: hero and text arrivals */
  --pop: cubic-bezier(0.34, 1.56, 0.64, 1);        /* spring:bouncy, scale only */
  --exit: cubic-bezier(0.55, 0.055, 0.675, 0.19);  /* cubic-in */
  --draw: cubic-bezier(0.215, 0.61, 0.355, 1);     /* cubic-out */
  --travel: cubic-bezier(0.65, 0, 0.35, 1);        /* smooth */
  position: absolute; inset: 0; overflow: hidden; background: var(--bg); color: var(--ink);
  font-family: inter, sans-serif; font-weight: 400;
}
.cam, .scene, .in { position: absolute; inset: 0; }
.cam { animation: push 15s var(--travel) 0s both; }
.glow {
  position: absolute; left: 1010px; top: 90px; width: 900px; height: 900px; border-radius: 50%;
  background: radial-gradient(circle, var(--accent-soft) 0%, transparent 68%); opacity: 0.5;
  animation: drift 15s var(--travel) 0s both;
}
.label { position: absolute; left: 160px; top: 250px; margin: 0; font-family: space-grotesk, sans-serif; font-size: 54px; letter-spacing: 6px; color: var(--muted); }
.hero { position: absolute; left: 160px; top: 300px; margin: 0; font-size: 184px; line-height: 1.05; letter-spacing: 3px; font-weight: 400; }
.sub { position: absolute; left: 160px; margin: 0; font-size: 86px; line-height: 1.1; }
.rule { position: absolute; left: 160px; width: 360px; height: 2px; background: var(--muted); transform-origin: left center; }

/* scene windows: the section fades out, its .in wrapper fades in (one opacity animation per element) */
.s1 { animation: scene-out 0.4s var(--exit) 2.5s both; }
.s2 { animation: scene-out 0.4s var(--exit) 5s both; }
.s3 { animation: scene-out 0.4s var(--exit) 8s both; }
.s4 { animation: scene-out 0.4s var(--exit) 12s both; }
.s2 .in { animation: scene-in 0.4s var(--travel) 2.5s both; }
.s3 .in { animation: scene-in 0.4s var(--travel) 5s both; }
.s4 .in { animation: scene-in 0.4s var(--travel) 8s both; }
.s5 .in { animation: scene-in 0.4s var(--travel) 12s both; }

/* 1  hook, 0-2.5 s: blur-in headline, ruled lines drawing */
.h1 { width: 1500px; animation: blur-in 0.9s var(--arrive) -0.15s both; }
.l1 { animation: slide-x 0.6s var(--arrive) 0.3s both; }
.r1 { top: 740px; animation: draw 0.8s var(--draw) 0.9s both; }
.ln { position: absolute; left: 1220px; height: 2px; background: var(--muted); transform-origin: left center; }
.a1 { top: 320px; width: 560px; animation: draw 0.8s var(--draw) 0.5s both; }
.a2 { top: 400px; width: 480px; animation: draw 0.8s var(--draw) 0.65s both; }
.a3 { top: 480px; width: 520px; animation: draw 0.8s var(--draw) 0.8s both; }

/* 2  problem, 2.5-5 s: words rise, a pile of note cards drops in */
.h2 { width: 1000px; font-size: 172px; }
.w { display: inline-block; animation: word 0.5s var(--arrive) calc(2.8s + var(--i) * 0.1s) both; }
.l2 { animation: slide-x 0.6s var(--arrive) 2.7s both; }
.r2 { top: 720px; animation: draw 0.8s var(--draw) 3.5s both; }
.pile { position: absolute; width: 420px; height: 270px; }
.p1 { left: 1300px; top: 170px; transform: rotate(-7deg); }
.p2 { left: 1340px; top: 320px; transform: rotate(4deg); }
.p3 { left: 1290px; top: 470px; transform: rotate(-3deg); }
.p4 { left: 1350px; top: 620px; transform: rotate(8deg); }
.card {
  width: 420px; height: 270px; box-sizing: border-box; border-radius: 24px; border: 1px solid var(--muted);
  background:
    linear-gradient(var(--muted) 0 0) 36px 44px / 220px 4px no-repeat,
    linear-gradient(var(--muted) 0 0) 36px 84px / 320px 4px no-repeat,
    linear-gradient(var(--muted) 0 0) 36px 124px / 280px 4px no-repeat,
    var(--surface);
  animation: drop 0.6s var(--arrive) calc(3s + var(--i) * 0.12s) both;
}

/* 3  product, 5-8 s: name, pitch, a frosted panel sketching a note */
.h3 { top: 300px; width: 900px; font-size: 248px; animation: rise 0.8s var(--arrive) 5.25s both; }
.l3 { animation: slide-x 0.6s var(--arrive) 5.2s both; }
.r3 { top: 600px; animation: draw 0.8s var(--draw) 5.8s both; }
.u3 { top: 640px; animation: rise 0.6s var(--arrive) 6.1s both; }
.panel {
  position: absolute; left: 1120px; top: 200px; width: 640px; height: 640px; box-sizing: border-box; border-radius: 28px; border: 1px solid var(--muted);
  background: color-mix(in srgb, var(--surface) 70%, transparent); backdrop-filter: blur(24px);
  animation: rise 0.8s var(--arrive) 5.4s both;
}
.bar { position: absolute; left: 48px; top: 56px; width: 260px; height: 8px; border-radius: 4px; background: var(--ink); transform-origin: left center; animation: draw 0.6s var(--draw) 5.9s both; }
.tx { position: absolute; left: 48px; height: 6px; border-radius: 3px; background: var(--muted); transform-origin: left center; }
.t1 { top: 130px; width: 560px; animation: draw 0.6s var(--draw) 6.1s both; }
.t2 { top: 176px; width: 500px; animation: draw 0.6s var(--draw) 6.25s both; }
.t3 { top: 222px; width: 540px; animation: draw 0.6s var(--draw) 6.4s both; }
.t4 { top: 268px; width: 380px; animation: draw 0.6s var(--draw) 6.55s both; }
.chip { position: absolute; left: 48px; top: 340px; width: 140px; height: 44px; border-radius: 22px; background: var(--accent); animation: pop 0.5s var(--pop) 7s both; }

/* 4  features, 8-12 s: three typographic rows, a marker steps down them */
.l4 { animation: slide-x 0.6s var(--arrive) 8.2s both; }
.row { position: absolute; left: 160px; width: 1400px; height: 110px; }
.ix { position: absolute; left: 0; top: 30px; font-family: space-grotesk, sans-serif; font-size: 54px; letter-spacing: 6px; color: var(--muted); }
.ft { position: absolute; left: 180px; top: 0; font-size: 100px; line-height: 110px; white-space: nowrap; }
.k1 { top: 340px; animation: slide-x 0.6s var(--arrive) 8.35s both; }
.k2 { top: 530px; animation: slide-x 0.6s var(--arrive) 9.25s both; }
.k3 { top: 720px; animation: slide-x 0.6s var(--arrive) 10.15s both; }
.hl { position: absolute; left: 160px; width: 1240px; height: 1px; background: var(--muted); transform-origin: left center; }
.m1 { top: 495px; animation: draw 0.7s var(--draw) 9.05s both; }
.m2 { top: 685px; animation: draw 0.7s var(--draw) 9.95s both; }
.pick { position: absolute; left: 112px; top: 383px; width: 24px; height: 24px; border-radius: 50%; background: var(--accent); animation: pick 3.6s var(--travel) 8.4s both; }

/* 5  end card, 12-15 s: dot, wordmark, one action, held */
.dot { position: absolute; left: 946px; top: 300px; width: 28px; height: 28px; border-radius: 50%; background: var(--accent); animation: pop 0.5s var(--pop) 12.15s both; }
.h5 { left: 0; top: 350px; width: 1920px; text-align: center; font-size: 248px; animation: land 0.8s var(--arrive) 12.2s both; }
.r5 { left: 780px; top: 660px; animation: draw 0.8s var(--draw) 12.75s both; }
.u5 { left: 0; top: 700px; width: 1920px; text-align: center; animation: rise 0.6s var(--arrive) 12.7s both; }

@keyframes push { from { transform: scale(1); } to { transform: scale(1.05); } }
@keyframes drift { from { transform: translate(0, 0); } to { transform: translate(-200px, 60px); } }
@keyframes scene-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes scene-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes slide-x { from { opacity: 0; transform: translateX(-40px); } to { opacity: 1; transform: none; } }
@keyframes blur-in { from { opacity: 0; filter: blur(12px); transform: translateY(24px); } to { opacity: 1; filter: blur(0); transform: none; } }
@keyframes rise { from { opacity: 0; transform: translateY(40px); } to { opacity: 1; transform: none; } }
@keyframes word { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes draw { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes drop { from { opacity: 0; transform: translateY(-70px) scale(0.96); } to { opacity: 1; transform: none; } }
@keyframes land { from { opacity: 0; transform: scale(1.08); } to { opacity: 1; transform: none; } }
@keyframes pop { from { opacity: 0; transform: scale(0.35); } to { opacity: 1; transform: scale(1); } }
@keyframes pick {
  0% { opacity: 0; transform: translateY(0) scale(0.35); }
  8% { opacity: 1; transform: translateY(0) scale(1); }
  22% { opacity: 1; transform: translateY(0) scale(1); }
  28% { opacity: 1; transform: translateY(190px) scale(1); }
  47% { opacity: 1; transform: translateY(190px) scale(1); }
  53%, 100% { opacity: 1; transform: translateY(380px) scale(1); }
}
